import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {
  
  // Consumo total de energía activa
  const active_energy_consumption = Number(input?.tsl_wo_work_order_attribute?.active_energy_consumption);
  
  if (isNaN(active_energy_consumption) || active_energy_consumption < 0) {
    return {
      ...input,
      result: {
        rule_description: `Invalid active_energy_consumption value: ${input?.tsl_wo_work_order_attribute?.active_energy_consumption}`,
        status: 'ERROR',
      }
    };
  }

  

  const rawpercentage_rate  = input?.percentage_pricing?.percentage_rate;

    // Validación explícita de null, undefined o string vacío
  if (rawpercentage_rate === undefined || rawpercentage_rate === null || String(rawpercentage_rate).trim() === "") {
    return {
      ...input,
      result: {
        rule_description: 'percentage_rate (percentage_rate) is missing or empty',
        status: 'ERROR',
      }
    };
  }

  const percentage_rate = Number(rawpercentage_rate);


  // Código del concepto de facturación a aplicar
  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!billingItemCode || billingItemCode === "null" || billingItemCode.trim() === "") {
    return {
      ...input,
      result: {
        rule_description: 'parameter_billingItem_code is missing or invalid',
        status: 'ERROR',
      }
    };
  }
  
  // Fuente de precios: estructura custom_graduated_pricing_with_percentage.prices
  const prices = Array.isArray(input?.custom_graduated_pricing_with_percentage?.prices)
    ? input.custom_graduated_pricing_with_percentage.prices
    : [];

  if (prices.length === 0) {
    return {
      ...input,
      result: {
        rule_description: 'No prices found in custom_graduated_pricing_with_percentage.prices',
        status: 'ERROR',
      }
    };
  }

  // Filtra por el code que corresponda al concepto
  const filteredRanges = prices
    .filter(r => r.code === billingItemCode)
    .sort((a, b) => Number(a.interval_high ?? 0) - Number(b.interval_high ?? 0))
    .map((r) => ({
      limite:
        Number(r.interval_high) === 999999999 || r.interval_high == null
          ? 999999999
          : Number(r.interval_high),
      precio: Number(r.base_price),
      porcentaje: Number(r.percentage ?? 1) / 100
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        rule_description: `No matching prices found for billingItemCode: ${billingItemCode}`,
        status: 'ERROR',
      }
    };
  }

  // Validar precios y porcentajes
  for (const range of filteredRanges) {
    if (isNaN(range.precio) || isNaN(range.porcentaje)) {
      return {
        ...input,
        result: {
          rule_description: `Invalid price or percentage in ranges: ${JSON.stringify(range)}`,
          status: 'ERROR',
        }
      };
    }
  }

  let importe_alumbrado = 0;
  let limite_anterior = 0;
  let i = 0;

  // Buscar el rango correspondiente al consumo
  for (; i < filteredRanges.length; i++) {
    const rango = filteredRanges[i];
    if (
      (active_energy_consumption >= limite_anterior && active_energy_consumption <= rango.limite && rango.limite !== 999999999) ||
      (active_energy_consumption >= limite_anterior && rango.limite === 999999999)
    ) {
      break;
    }
    limite_anterior = rango.limite;
  }

  // Fallback: si el consumo supera los límites definidos
  if (i >= filteredRanges.length) i = filteredRanges.length - 1;

  // Regla de cálculo: comparar precio * porcentaje con la constante
  if (filteredRanges[i].precio * filteredRanges[i].porcentaje < percentage_rate) {
    importe_alumbrado = filteredRanges[i].precio;
  } else {
    importe_alumbrado = percentage_rate;
  }

  // Buscar el billing item correspondiente en la estructura de facturación
  const billingItems = input?.tsl_wo_work_order_attribute?.billing_items?.public_lighting_billing_items ?? [];
  const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);

  if (!billingItem) {
    return {
      ...input,
      result: {
        rule_description: `The billingItemCode ${billingItemCode} could not be found in billing_items.public_lighting_billing_items`,
        status: 'ERROR',
      }
    };
  }

  // Asignar el importe calculado
  billingItem.billing_item_amount = importe_alumbrado;

  // Retornar resultado
  return {
    ...input,
    result: {
      total_amount: importe_alumbrado,
      status: 'OK',
      rule_description: 'Alumbrado publico-Precio por rangos de consumo amount calculation rule completed',
    },
  };
};
